import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
mkdirSync('/tmp/opencode/shots2', { recursive: true })
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
const errors = []
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR:', e.message) })
page.on('console', m => { if (m.type() === 'error') { errors.push(m.text()); console.log('CONSOLE:', m.text()) } })
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForFunction(() => document.fonts.status === 'loaded')
await page.evaluate(() => document.querySelector('#start-button').click())
await page.waitForTimeout(900)
const state = async (label) => {
  const s = await page.evaluate(() => ({ ...window.__outside.state, pos: window.__outside.position, yaw: window.__outside.yaw, colliders: window.__outside.colliderCount, dist: document.querySelector('#objective-distance').textContent, mission: document.querySelector('#mission-title').textContent, collapsed: document.querySelector('#mission-card').classList.contains('collapsed'), puzzle: !document.querySelector('#puzzle-screen').classList.contains('hidden'), dialogue: !document.querySelector('#dialogue-screen').classList.contains('hidden'), dialogueText: document.querySelector('#dialogue-text').textContent, ending: !document.querySelector('#ending-screen').classList.contains('hidden') }))
  console.log(label, JSON.stringify(s))
  return s
}
await state('start')
await page.screenshot({ path: '/tmp/opencode/shots2/game-start.png' })
// mission toggle
await page.locator('#mission-toggle').click(); await page.waitForTimeout(250)
console.log('toggle expanded', await page.locator('#mission-card').getAttribute('class'))
await page.screenshot({ path: '/tmp/opencode/shots2/game-mission-expanded.png' })
await page.locator('#mission-toggle').click(); await page.waitForTimeout(200)
// solid wall collision at archive south of door
await page.evaluate(() => { window.__outside.teleport(-10, 0); window.__outside.setYaw(0) })
await page.waitForTimeout(100)
await page.keyboard.down('a'); await page.waitForTimeout(2500); await page.keyboard.up('a')
await page.waitForTimeout(100)
const wallStop = await state('wall-stop')
console.log('wall blocked:', wallStop.pos.x > -16 && wallStop.pos.x < -15)
// door entry at z=4
await page.evaluate(() => { window.__outside.teleport(-10, 4); window.__outside.setYaw(0) })
await page.waitForTimeout(100)
await page.keyboard.down('a'); await page.waitForTimeout(3300); await page.keyboard.up('a')
await page.waitForTimeout(100)
const inside = await state('door-entry')
console.log('entered archive:', inside.pos.x < -16)
await page.screenshot({ path: '/tmp/opencode/shots2/archive-interior.png' })
// solve archive puzzle
await page.evaluate(() => { window.__outside.teleport(-28.4, 4); window.__outside.setYaw(0) })
await page.waitForTimeout(300)
await page.keyboard.press('e'); await page.waitForTimeout(300)
const puzzleOpen = await state('archive-puzzle')
if (!puzzleOpen.puzzle) throw new Error('archive puzzle did not open')
const clickSlot = async (slot, n) => { for (let i = 0; i < n; i++) { await page.locator(`#tone-row [data-slot="${slot}"]`).click(); await page.waitForTimeout(60) } }
await clickSlot(0, 2); await clickSlot(1, 1); await clickSlot(2, 4)
await page.locator('#puzzle-submit').click(); await page.waitForTimeout(500)
const passState = await state('archive-solved')
if (!passState.pass) throw new Error('pass not collected')
// NPC dialogue
await page.evaluate(() => window.__outside.teleport(-31.2, 7.4))
await page.waitForTimeout(250)
await page.keyboard.press('e'); await page.waitForTimeout(350)
const talk = await state('dialogue-open')
if (!talk.dialogue || !talk.dialogueText) throw new Error('dialogue did not open')
await page.screenshot({ path: '/tmp/opencode/shots2/dialogue.png' })
await page.locator('#dialogue-next').click(); await page.waitForTimeout(150)
await page.locator('#dialogue-next').click(); await page.waitForTimeout(150)
await page.locator('#dialogue-next').click(); await page.waitForTimeout(250)
const closed = await state('dialogue-closed')
if (closed.dialogue) throw new Error('dialogue did not close')
// relay 1
await page.evaluate(() => window.__outside.teleport(-2, -27.6))
await page.waitForTimeout(300)
await page.keyboard.press('e'); await page.waitForTimeout(250)
await clickSlot(0, 1); await clickSlot(1, 3); await clickSlot(2, 4)
await page.locator('#puzzle-submit').click(); await page.waitForTimeout(400)
await state('relay-1')
// relay 2 inside signal house
await page.evaluate(() => { window.__outside.teleport(26.8, 3); window.__outside.setYaw(0) })
await page.waitForTimeout(300)
await page.keyboard.press('e'); await page.waitForTimeout(250)
await clickSlot(0, 2); await clickSlot(1, 4); await clickSlot(2, 1)
await page.locator('#puzzle-submit').click(); await page.waitForTimeout(400)
await state('relay-2')
await page.screenshot({ path: '/tmp/opencode/shots2/signal-interior.png' })
// relay 3
await page.evaluate(() => window.__outside.teleport(3, 35.4))
await page.waitForTimeout(300)
await page.keyboard.press('e'); await page.waitForTimeout(250)
await clickSlot(0, 3); await clickSlot(1, 2); await clickSlot(2, 1)
await page.locator('#puzzle-submit').click(); await page.waitForTimeout(500)
await state('relay-3')
// gate
await page.evaluate(() => window.__outside.teleport(0, -62))
await page.waitForTimeout(300)
await page.keyboard.press('e'); await page.waitForTimeout(500)
const end = await state('ending')
if (!end.ending) throw new Error('ending did not open')
await page.screenshot({ path: '/tmp/opencode/shots2/ending.png' })
console.log('ERRORS', JSON.stringify(errors))
await browser.close()
if (errors.length) process.exit(2)

